from pathlib import Path
import json
r=Path(__file__).resolve().parents[1]
summary=json.loads((r/'results/numerical_summary.json').read_text(encoding='utf8'))
compact=json.dumps({key:{'points':v['points'],'fit':v['fit']['newton_yukawa_offset']} for key,v in summary['scenarios'].items()},ensure_ascii=False,separators=(',',':'))
tmpl=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>ROOT V84｜多距离引力实验</title>
<style>
:root{color-scheme:dark;--bg:#0a1121;--panel:#131f32;--border:#263b53;--muted:#a2b3c5;--accent:#5cdbd3;--alt:#e6ab67;--text:#ebf4fd}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top right,#163553,#0a1121 58%);color:var(--text);font-family:system-ui,-apple-system,"Microsoft YaHei",sans-serif;line-height:1.55}
header,main,footer{max-width:1200px;margin:auto;padding:20px 24px}header{padding-top:34px}.kicker{font-size:12px;color:var(--accent);letter-spacing:.18em;font-weight:700}h1{font-size:clamp(24px,4vw,38px);line-height:1.24;margin:10px 0}h2{font-size:18px;margin:0 0 12px}h3{font-size:14px;margin:0 0 8px}.note{color:var(--muted);max-width:800px;font-size:14px}.important{border-left:3px solid #e6ab67;background:#3a291e;padding:12px 16px;border-radius:3px;font-size:13px}
.grid{display:grid;grid-template-columns:340px minmax(0,1fr);gap:16px}.panel{border:1px solid var(--border);border-radius:14px;background:rgba(19,31,50,.95);padding:20px;box-shadow:0 7px 35px #03091522}.span2{grid-column:1/-1}.controls label{display:block;margin:12px 0 2px;color:#d3e5f0;font-size:13px}.controlval{float:right;color:var(--accent);font-variant-numeric:tabular-nums}.controls input[type=range]{width:100%;accent-color:var(--accent)}select{width:100%;padding:9px;background:#0a1324;color:var(--text);border:1px solid var(--border);border-radius:8px}
canvas{width:100%;height:275px;background:#0c1627;border:1px solid #26384e;border-radius:9px;display:block}.statgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}.stat{background:#0d1929;border:1px solid #26384e;padding:12px;border-radius:9px}.stat small{display:block;color:var(--muted);font-size:11px}.stat strong{display:block;font-size:17px;font-weight:700;margin-top:4px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.chip{font-size:10px;font-weight:700;display:inline-block;background:#193a45;color:#9de7dd;border-radius:6px;padding:5px 8px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;border-bottom:1px solid #293b50;padding:8px}th{color:#a8d5e9;font-size:12px}td{font-variant-numeric:tabular-nums}button{background:#1b374a;border:1px solid #3a5969;padding:9px 15px;color:white;border-radius:9px;cursor:pointer}button.selected{background:#28677b;border-color:#7ae4df}.buttons{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.legend{display:flex;gap:17px;color:var(--muted);font-size:12px;margin-top:8px}.dot{width:9px;height:9px;display:inline-block;border-radius:50%;margin-right:5px}footer{color:var(--muted);font-size:12px;padding-bottom:35px}
@media(max-width:850px){.grid{grid-template-columns:1fr}.columns{grid-template-columns:1fr}.statgrid{grid-template-columns:1fr}header,main,footer{padding-left:14px;padding-right:14px}}
</style></head><body><header><div class="kicker">ROOT RESEARCH LABORATORY / V84</div><h1>多距离引力与候选第五力辨识实验室</h1><p class="note">统一球形源质量 · 双传感器奇偶信号 · 有限程 Yukawa 假说 · 假动作与同形伪差反例。<b>全部观测数据均为合成模拟，未连接真实硬件。</b></p><div class="important">即使拟合得到显著的“第五力强度”，如果仪器伪差具有相同的距离规律，也不能宣告发现新力或引力常数改变。</div></header>
<main class="grid">
<section class="panel controls"><h2>物理参数控制</h2><label>源质量 M <span class="controlval" id="valM"></span></label><input id="mass" type="range" min="20" max="250" value="100" step="5"><label>中心距离 d <span class="controlval" id="valD"></span></label><input id="distance" type="range" min="0.28" max="1.65" value="0.50" step="0.01"><label>半基线 s <span class="controlval" id="valS"></span></label><input id="baseline" type="range" min="0.04" max="0.15" value="0.10" step="0.005"><label>球半径 a <span class="controlval" id="valA"></span></label><input id="radius" type="range" min="0.05" max="0.15" value="0.12" step="0.005"><label>候选新力范围 λ <span class="controlval" id="valL"></span></label><input id="range" type="range" min="0.08" max="2.0" value="0.25" step="0.01"><label>候选强度 α <span class="controlval" id="valAl"></span></label><input id="alpha" type="range" min="0" max="0.30" value="0.08" step="0.005"><div id="error" class="important" style="display:none;margin-top:14px"></div><div class="statgrid"><div class="stat"><small>Newton 共模奇幅度</small><strong id="nstat">—</strong></div><div class="stat"><small>候选额外幅度</small><strong id="ystat">—</strong></div><div class="stat"><small>梯度偶信号</small><strong id="gstat">—</strong></div></div><p class="note">单位分别为 nm/s²、nm/s²、s⁻²。α 是假设参数，不代表新力观测值。</p></section>
<section class="panel"><h2>距离规律：能否与 Newton 引力区分？</h2><canvas id="curve" width="820" height="340" aria-label="理论曲线图"></canvas><div class="legend"><span><i class="dot" style="background:#5cdbd3"></i>Newton</span><span><i class="dot" style="background:#e6ab67"></i>Newton + 候选新力</span></div><p class="note">在 λ 很大时两条曲线趋于共线，无法仅凭这些距离数据分开 β 与 α。</p></section>
<section class="panel span2"><h2>合成数据的关键反例：显著性不等于发现</h2><div class="buttons"><button class="selected" data-scenario="NULL">无新力（零假设）</button><button data-scenario="INJECTED">人工注入第五力</button><button data-scenario="CONFOUNDED">只有同形仪器伪差</button></div><div class="columns"><div><canvas id="observed" width="820" height="340" aria-label="多距离合成观测"></canvas><p class="note">点和误差棒为固定随机种子的人工合成数据，虚线为标准 Newton 预测。</p></div><div><div class="statgrid"><div class="stat"><small>拟合 α</small><strong id="fitAlpha"></strong></div><div class="stat"><small>α / 统计标准误</small><strong id="fitZ"></strong></div><div class="stat"><small>χ² / 自由度</small><strong id="fitChi"></strong></div></div><p id="explanation" class="important" style="margin-top:16px"></p><h3>数学识别条件</h3><p class="note">模型 y(d)=β C_N(d)+α C_Y(d;λ)+b。只有设计矩阵三列独立，β、α、b 才能在所设统计模型下分开。**同形背景**与假设性新力不可能仅靠这组观测区分。</p></div></div></section>
<section class="panel span2"><h2>实验前必须通过的验证门槛</h2><div class="columns"><table><thead><tr><th>必要实验步骤</th><th>失败就不能宣告突破</th></tr></thead><tbody><tr><td>有源/假动作 ABBA</td><td>同形执行伪差</td></tr><tr><td>多距离与多质量</td><td>仅测到 GM，背景重合</td></tr><tr><td>倾角、震动、电磁记录</td><td>仪器串扰</td></tr><tr><td>多半径同质量源</td><td>有限源形状校核</td></tr><tr><td>第二种仪器独立复现</td><td>单设备系统误差</td></tr><tr><td>提前规定 λ 和统计量</td><td>事后挑选显著结果</td></tr></tbody></table><div><h3>科学状态</h3><p class="note">Newton 源质量引力与 ABBA 奇偶抵消属于已知理论中的可证明部分。Yukawa 力、α 参数和伪差信号都属于候选或合成模型。本实验没有通过硬件采集，也不能决定普适常数 G，更不能证明四力大统一。</p><p class="note">数据与推导见 <code>book/</code>、<code>data/</code>、<code>results/</code>，可通过 <code>python run_all.py</code> 独立复算。</p></div></div></section>
</main><footer>ROOT V84 / SYNTHETIC_NOT_REAL_DATA / No physical device control / CODATA 2022 G reference</footer>
<script>
'use strict';
const BASE=__SUMMARY__;
const G=6.67430e-11;
const ids=['mass','distance','baseline','radius','range','alpha'];let scenario='NULL';
function get(){return {M:+document.getElementById('mass').value,d:+document.getElementById('distance').value,s:+document.getElementById('baseline').value,a:+document.getElementById('radius').value,l:+document.getElementById('range').value,alpha:+document.getElementById('alpha').value};}
function formFactor(x){if(x<.02)return 1+x*x/10+x**4/280+x**6/15120;return 3*(x*Math.cosh(x)-Math.sinh(x))/x**3}
function kernel(a,r,l){let x=a/l;if(x<.02)return formFactor(x)*Math.exp(-r/l);return 1.5/x**3*((x-1)*Math.exp(-(r-a)/l)+(x+1)*Math.exp(-(r+a)/l))}
function calc(v,d){let {M,s,a,l}=v;if(d<=s+a)return null;let a1=d-s,a2=d+s,n=G*M/2*(a1**-2+a2**-2);let y=G*M/2*((1+a1/l)*kernel(a,a1,l)/a1**2+(1+a2/l)*kernel(a,a2,l)/a2**2);let gr=G*M/(2*s)*(a1**-2-a2**-2);return {n,y,gr}}
function fmt(v,n=3){return Number.isFinite(v)?v.toExponential(n):'—'}
function paint(canvas,series,points){let ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);const pad={l:75,r:23,t:20,b:45};ctx.fillStyle='#0c1627';ctx.fillRect(0,0,w,h);
const all=[...series.flatMap(s=>s.points),...points];const xv=all.map(p=>p[0]),yv=all.map(p=>p[1]).filter(z=>z>=0);if(!xv.length||!yv.length)return;let xmin=Math.min(...xv),xmax=Math.max(...xv),ymax=Math.max(...yv)*1.13,ymin=0;
const X=x=>pad.l+(x-xmin)/(xmax-xmin||1)*(w-pad.l-pad.r),Y=y=>h-pad.b-(y-ymin)/(ymax-ymin||1)*(h-pad.t-pad.b);
ctx.lineWidth=1;ctx.strokeStyle='#3a5066';ctx.font='12px sans-serif';ctx.fillStyle='#9db2c6';for(let i=0;i<=5;i++){let y=ymin+(ymax-ymin)*i/5;let yy=Y(y);ctx.beginPath();ctx.moveTo(pad.l,yy);ctx.lineTo(w-pad.r,yy);ctx.stroke();ctx.fillText((y/1e-9).toFixed(1),15,yy+4)}for(let i=0;i<=5;i++){let x=xmin+(xmax-xmin)*i/5;let xx=X(x);ctx.fillText(x.toFixed(2),xx-12,h-15)}ctx.fillText('d (m)',w/2,h-6);ctx.save();ctx.translate(12,h/2);ctx.rotate(-Math.PI/2);ctx.fillText('nm/s²',0,0);ctx.restore();
for(let se of series){ctx.beginPath();se.points.forEach((p,i)=>{if(i===0)ctx.moveTo(X(p[0]),Y(p[1]));else ctx.lineTo(X(p[0]),Y(p[1]))});ctx.lineWidth=2.5;ctx.strokeStyle=se.color;ctx.stroke()}
for(let p of points){let xx=X(p[0]),yy=Y(p[1]);ctx.fillStyle='#f5d6ab';ctx.beginPath();ctx.arc(xx,yy,4.1,0,Math.PI*2);ctx.fill();if(p[2]){ctx.strokeStyle='#f5d6ab';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(xx,Y(p[1]-p[2]));ctx.lineTo(xx,Y(p[1]+p[2]));ctx.stroke()}}
}
function update(){let v=get();const labels={'mass':`${v.M.toFixed(0)} kg`,'distance':`${v.d.toFixed(2)} m`,'baseline':`${v.s.toFixed(3)} m`,'radius':`${v.a.toFixed(3)} m`,'range':`${v.l.toFixed(2)} m`,'alpha':`${v.alpha.toFixed(3)}`};['mass','distance','baseline','radius','range','alpha'].forEach((id,i)=>document.getElementById(['valM','valD','valS','valA','valL','valAl'][i]).textContent=labels[id]);let error=document.getElementById('error');error.style.display=v.d<=v.s+v.a?'block':'none';error.textContent='当前几何不合法：d 必须大于 s+a（两个传感器位于球外）。';let q=calc(v,v.d);['nstat','ystat','gstat'].forEach(k=>document.getElementById(k).textContent='—');if(q){document.getElementById('nstat').textContent=fmt(q.n/1e-9)+' nm/s²';document.getElementById('ystat').textContent=fmt(v.alpha*q.y/1e-9)+' nm/s²';document.getElementById('gstat').textContent=fmt(q.gr)+' s⁻²'}
let ds=[];for(let d=Math.max(.24,v.s+v.a+.003);d<1.66;d+=.009){let p=calc(v,d);if(p)ds.push([d,p])}paint(document.getElementById('curve'),[{color:'#5cdbd3',points:ds.map(z=>[z[0],z[1].n])},{color:'#e6ab67',points:ds.map(z=>[z[0],z[1].n+v.alpha*z[1].y])}],[]);updateMeasured()}
function updateMeasured(){const x=BASE[scenario],pts=x.points;let theory=pts.map(p=>[p.distance_m,p.newton_m_s2]);let fit=x.fit;paint(document.getElementById('observed'),[{color:'#5cdbd3',points:theory}],pts.map(p=>[p.distance_m,p.signal,p.sem]));document.getElementById('fitAlpha').textContent=fit.alpha_yukawa.toFixed(4)+' ± '+fit.alpha_se.toFixed(4);document.getElementById('fitZ').textContent=(fit.alpha_yukawa/fit.alpha_se).toFixed(2)+'σ';document.getElementById('fitChi').textContent=fit.chi_square.toFixed(2)+' / '+fit.dof;document.getElementById('explanation').textContent=({'NULL':'合成数据无新力，拟合 α 在误差范围内接近 0。','INJECTED':'仅在合成数据中人为注入 α=0.08；恢复能力不代表发现真实新力。','CONFOUNDED':'关键反例：真实新力 α=0；装置有与候选模型同形伪差。拟合照样显著，无法由数据独自区分。'})[scenario]}
ids.forEach(id=>document.getElementById(id).addEventListener('input',update));document.querySelectorAll('[data-scenario]').forEach(b=>b.addEventListener('click',()=>{scenario=b.dataset.scenario;document.querySelectorAll('[data-scenario]').forEach(x=>x.classList.toggle('selected',x===b));updateMeasured()}));update();
</script></body></html>'''
(r/'web'/'index.html').write_text(tmpl.replace('__SUMMARY__',compact),encoding='utf8')
